//----- (th4) ------------------------------------------------------------
// Single lookup seam for monster display names. Returns a translated name for
// the active language, or the English name when there is no translation.
// (th4) Indonesian monster/boss names (defined in LocalizationID.cpp)
extern const char* ID_MonsterName( int id );
extern const char* ID_UniqueMonsterName( int id );
extern const char* PT_MonsterName( int id );        // (th4) Portuguese
extern const char* PT_UniqueMonsterName( int id );
extern const char* ES_MonsterName( int id );        // (th4) Spanish
extern const char* ES_UniqueMonsterName( int id );
extern const char* CHI_UniqueMonsterName( int id );   // (th4) Chinese
extern const char* IT_MonsterName( int id );         // (th4) Italian
extern const char* IT_UniqueMonsterName( int id );
extern const char* FR_MonsterName( int id );         // (th4) French
extern const char* FR_UniqueMonsterName( int id );
extern const char* DE_MonsterName( int id );         // (th4) German
extern const char* DE_UniqueMonsterName( int id );
extern const char* PL_MonsterName( int id );         // (th4) Polish
extern const char* KO_MonsterName( int id );         // (th4) Korean
extern const char* PL_UniqueMonsterName( int id );
extern const char* KO_UniqueMonsterName( int id );
extern const char* CHI_MonsterName( int id );        // (th4) Chinese

const char* LocalizedMonsterName( const BaseMonster* bm )
{
	if( GameLanguage == LANG_ID ){
		const char* t = ID_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_PT ){
		const char* t = PT_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_ES ){
		const char* t = ES_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_TR ){
		const char* t = TR_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_DA ){
		const char* t = DA_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_NL ){
		const char* t = NL_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_BG ){
		const char* t = BG_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_UK ){
		const char* t = UK_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_JA ){
		const char* t = JA_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_AR ){
		const char* t = AR_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_HIN ){   // (th4) Hindi
		const char* t = HIN_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_SW ){   // (th4) Swahili
		const char* t = SW_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_CS ){   // (th4) Czech
		const char* t = CS_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_HR ){   // (th4) Croatian
		const char* t = HR_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_IT ){
		const char* t = IT_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_FR ){
		const char* t = FR_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_DE ){
		const char* t = DE_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_PL ){
		const char* t = PL_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_CHI ){
		const char* t = CHI_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_KO ){          // (th4) Korean
		const char* t = KO_MonsterName( bm->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage != LANG_EN && uint( bm->id ) < BM_COUNT ){
		const char* t = MonsterNameLoc[ bm->id ][ GameLanguage ];
		if( t && t[0] ) return t;          // have a translation
	}
	return bm->name;                       // English fallback
}

