{
	if( GameLanguage == LANG_ID && um ){
		const char* t = ID_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_PT && um ){
		const char* t = PT_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_ES && um ){
		const char* t = ES_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_TR && um ){
		const char* t = TR_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_DA && um ){
		const char* t = DA_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_BG && um ){
		const char* t = BG_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_UK && um ){
		const char* t = UK_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_JA && um ){
		const char* t = JA_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_AR && um ){
		const char* t = AR_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_HIN && um ){   // (th4) Hindi
		const char* t = HIN_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_SW && um ){   // (th4) Swahili
		const char* t = SW_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_CS && um ){   // (th4) Czech
		const char* t = CS_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_HR && um ){   // (th4) Croatian
		const char* t = HR_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_NL && um ){
		const char* t = NL_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_IT && um ){
		const char* t = IT_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_FR && um ){
		const char* t = FR_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_DE && um ){
		const char* t = DE_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_PL && um ){
		const char* t = PL_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_CHI && um ){       // (th4) Chinese
		const char* t = CHI_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage == LANG_KO && um ){        // (th4) Korean
		const char* t = KO_UniqueMonsterName( um->id );
		if( t && t[0] ) return t;
	}
	if( GameLanguage != LANG_EN && um && uint( um->id ) < UM_count ){
		const char* t = UniqueMonsterNameLoc[ um->id ][ GameLanguage ];
		if( t && t[0] ) return t;
	}
	return um ? um->NamePtr : 0;
}


// =============================================================================
//  UI string translation — L(en) returns the localized string for the active
//  language, or the English string itself. Used for NPC/store menus and any
//  other UI literal. struct UiStr is ALSO used by UniqueItemStrings below, so
//  this block must precede it. Table is CP1251; %i / layout spaces preserved.
// =============================================================================
struct UiStr { const char* en; const char* ru; };

// =============================================================================
//  (th4) SCALABLE MULTI-LANGUAGE OVERLAY REGISTRY
//  -----------------------------------------------------------------------------
//  The original localization stored one translation per row ({en, ru}). To let
//  several non-English languages coexist WITHOUT editing every RU row or growing
//  each struct to N columns, translations are looked up through a registry:
//
//    * Every string-keyed table is identified by an OVL_* id.
//    * Each language registers, per table id, a {pointer,count} pair.
//    * A translation is { const char* en; const char* tr; } == UiStr, so RU's
//      existing tables are reused verbatim (ru column IS the tr column) and a new
//      language only supplies its own arrays.
//    * xlate(id,en) / xlateIdx(id,index,en) resolve against the ACTIVE language's
//      registered table, English-fallback on any miss.
//
//  Index-keyed tables (speech / on-screen / quests) use IdxStr instead of UiStr.
//  Adding a language = fill these arrays in a new file + one register call in
//  InitLanguageOverlays(). English (LANG_EN) never has overlays: it is the base.
// =============================================================================
struct IdxStr { int index; const char* tr; };

enum {
	OVL_UI = 0, OVL_MENU, OVL_UNIQUE_ITEM, OVL_AFFIX_PREFIX, OVL_AFFIX_SUFFIX,
	OVL_BASE_ITEM, OVL_BASE_NAME2, OVL_ELEMENT, OVL_SPICIES, OVL_ICEAGE,
	OVL_SPELL, OVL_SPELL_NOM, OVL_PERK_NAME, OVL_PERK_DESC, OVL_WARP,
	// (th4) OVL_WARP_OBL: warp name in the oblique case the "To %s" header governs --
	// accusative in RU, genitive in PL. Appended last so no existing id renumbers.
	// Every X_GetStrTable() returns {0,0} for an unknown id, so locs that register
	// nothing here are unaffected and keep the nominative.
	OVL_WARP_OBL,
	OVL_STR_COUNT
};
enum { OVL_SPEECH = 0, OVL_ONSCREEN, OVL_QUEST, OVL_IDX_COUNT };

struct StrTableRef { const UiStr*  tbl; int n; };
struct IdxTableRef { const IdxStr* tbl; int n; };

static StrTableRef g_StrOverlay[ LANG_COUNT ][ OVL_STR_COUNT ] = {};
static IdxTableRef g_IdxOverlay[ LANG_COUNT ][ OVL_IDX_COUNT ] = {};

static void registerStrTable( int lang, int id, const UiStr* tbl, int n )
{ if( lang > LANG_EN && lang < LANG_COUNT && id < OVL_STR_COUNT ) { g_StrOverlay[lang][id].tbl = tbl; g_StrOverlay[lang][id].n = n; } }
static void registerIdxTable( int lang, int id, const IdxStr* tbl, int n )
{ if( lang > LANG_EN && lang < LANG_COUNT && id < OVL_IDX_COUNT ) { g_IdxOverlay[lang][id].tbl = tbl; g_IdxOverlay[lang][id].n = n; } }

// Generic resolvers. Both English and an unregistered/empty table -> English.
static const char* xlate( int id, const char* en )
{
	if( GameLanguage == LANG_EN || !en || !en[0] ) return en;
	const StrTableRef& r = g_StrOverlay[ GameLanguage ][ id ];
	for( int i = 0; i < r.n; i++ )
		if( r.tbl[i].en[0] == en[0] && !strcmp( r.tbl[i].en, en ) ) return r.tbl[i].ru;
	return en;
}
static char* xlateIdx( int id, int index, char* en )
{
	if( GameLanguage == LANG_EN ) return en;
	const IdxTableRef& r = g_IdxOverlay[ GameLanguage ][ id ];
	for( int i = 0; i < r.n; i++ )
		if( r.tbl[i].index == index ) return (char*)r.tbl[i].tr;
	return en;
}

