		case TraitId::Capitalist: return "\x8D\x80\x97\x80\x8B\x9C\x8D\x8E\x85 \x8D\x80\x95\x8E\x86\x84\x85\x8D\x88\x85 \x87\x8E\x8B\x8E\x92\x80 \x91\x8D\x88\x86\x85\x8D\x8E \x8D\x80 33%";
		case TraitId::Frenzied: return "-40% \x8A \x8C\x80\x8A\x91\x88\x8C\x80\x8B\x9C\x8D\x8E\x8C\x93 \x98\x80\x8D\x91\x93 \x8F\x8E\x8F\x80\x84\x80\x8D\x88\x9F \x8F\x8E \x96\x85\x8B\x88";
