//----- (th4) -------------------------------------------------------------
// (th4) DC mission 15: the Anvil of Fury rewards are handed over by Hephasto, not
// Griswold, so his name comes off them. Applied to the LOCALIZED name rather than the
// English one, because every language renders the smith differently -- some put him
// first, some last, and the Slavic and Turkish forms carry case endings:
//
//   EN  Griswold's Edge      DE  Griswolds Schneide     PL  Krawedz Griswolda
//   ES  Filo de Griswold     RU  Klinok Grisvolda       TR  Griswold'un Agzi
//
// Swapping the English key before localization would instead miss every table entry and
// drop all ten languages back to English.
void DarkCampaignRenameSmith( char* name, int nameSize )
{
	if( GameMode != GM_DARK_CAMPAIGN || !name || !name[0] ) return;
	const char* from = 0;
	const char* to   = 0;
	switch( GameLanguage ){
		case LANG_EN  : from = "Griswold's"; to = "Hephasto's"; break;
		case LANG_RU  : from = "\xC3\xF0\xE8\xF1\xE2\xEE\xEB\xFC\xE4\xE0"; to = "\xC3\xE5\xF4\xE0\xF1\xF2\xEE"; break;
		case LANG_ID  : from = "Griswold"; to = "Hephasto"; break;
		case LANG_PT  : from = "Griswold"; to = "Hephasto"; break;
		case LANG_ES  : from = "Griswold"; to = "Hephasto"; break;
		case LANG_IT  : from = "Griswold"; to = "Hephasto"; break;
		case LANG_FR  : from = "Griswold"; to = "Hephasto"; break;
		case LANG_DE  : from = "Griswolds"; to = "Hephastos"; break;
		case LANG_PL  : from = "Griswolda"; to = "Hephasta"; break;
		case LANG_CHI : from = "\xB8\xF1\xC0\xEF\xCB\xB9\xCE\xD6\xB5\xC2"; to = "\xBA\xD5\xB7\xC6\xCB\xB9\xCD\xD0"; break;
		case LANG_TR  : from = "Griswold'un"; to = "Hephasto'nun"; break;
		case LANG_DA  : from = "Griswolds"; to = "Hephastos"; break;	// (th4) Danish genitive
		case LANG_NL  : from = "Griswolds"; to = "Hephastos"; break;	// (th4) Dutch: same possessive -s
		case LANG_SW  : from = "Griswold"; to = "Hephasto"; break;	// (th4) Swahili: possession is a separate word ("wa Griswold"), so the name is bare
		case LANG_CS  : from = "Griswolda"; to = "Hephasta"; break;	// (th4) Czech: the CS tables always write his possessive as the genitive "Griswolda" (LocalizationCS.cpp header)
		case LANG_HR  : from = "Griswolda"; to = "Hephasta"; break;	// (th4) Croatian: the HR tables write his possessive as the genitive "Griswolda" too
		case LANG_BG  : from = "\xC3\xF0\xE8\xF1\xF3\xEE\xEB\xE4"; to = "\xD5\xE5\xF4\xE0\xF1\xF2\xEE"; break;
		case LANG_UK  : from = "\xC3\xF0i\xF1\xE2\xEE\xEB\xE4\xE0"; to = "\xC3\xE5\xF4\xE0\xF1\xF2\xE0"; break;  // (th4) Ukrainian: item/speech tables use the GENITIVE "Hrisvolda" -> "Hefasta"	// (th4) Bulgarian: no genitive case, plain nominative swap
		case LANG_KO  : from = "\xB1\xD7\xB8\xAE\xBD\xBA\xBF\xF9\xB5\xE5"; to = "\xC7\xEC\xC6\xC4\xBD\xBA\xC5\xE4"; break;	// (th4) Korean, EUC-KR
		case LANG_JA  : from = "\xA5\xB0\xA5\xEA\xA5\xB9\xA5\xA6\xA5\xA9\xA5\xEB\xA5\xC9"; to = "\xA5\xD8\xA5\xD5\xA5\xA1\xA5\xB9\xA5\xC8"; break;	// (th4) Japanese, EUC-JP: Gurisuworudo -> Hefasuto; possessive "no" follows the name
		case LANG_AR  : from = "\xA1\xBA\xA1\xB1\xA1\xC4\xA1\xB3\xA1\xC2\xA1\xC2\xA1\xBE\xA1\xAF"; to = "\xA1\xC1\xA1\xC4\xA1\xBB\xA1\xA7\xA1\xB3\xA1\xAA\xA1\xC2"; break;	// (th4) Arabic, stored LOGICAL (shaped at draw time), so a plain swap is safe
		case LANG_HIN : from = "\xAE\xD8\xAD\xCC\xAC\xE2\xAE\xCF\xA5\xC5"; to = "\xAE\xA4\xA8\xF8\xAE\xC3\xA6\xE5"; break;	// (th4) Hindi, pre-shaped cells: the name is a whole word, so its cells do not depend on neighbours
	}
	if( !from || !to ) return;

	char* at = strstr( name, from );
	if( !at ) return;

	const int fromLen = (int)strlen(from);
	const int toLen   = (int)strlen(to);
	const int tailLen = (int)strlen(at + fromLen);
	const int head    = (int)(at - name);
	if( head + toLen + tailLen + 1 > nameSize ) return;	// would not fit: leave it alone

	// NOT strcpy: common.h macros it to strncpy_s(dst, src, _TRUNCATE), whose template
	// parameter is char(&)[_Size] and binds only to an ARRAY -- "at" and "at + toLen" are
	// plain char*, so it will not compile. memmove/memcpy take pointers and are what this
	// wants anyway, since head and tail can overlap when the two names differ in length.
	memmove( at + toLen, at + fromLen, tailLen );
	memcpy( at, to, toLen );
	at[ toLen + tailLen ] = 0;
}

//----- (th4) ------------------------------------------------------------
// Translate a unique item name (English -> active language, else English).
const char* LocalizedUniqueItemName( const char* en )
{
	return xlate( OVL_UNIQUE_ITEM, en );
}

