extern const char* FR_GCInfoName( int gc );   // (th4) French
extern const char* FR_GCInfoDesc( int gc );
extern const char* DE_GCInfoName( int gc );   // (th4) German
extern const char* DE_GCInfoDesc( int gc );
extern const char* PL_GCInfoName( int gc );   // (th4) Polish
extern const char* KO_GCInfoName( int gc );   // (th4) Korean
